  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Calculates the final price of this trip after applying a 20% discount if the customer has a DISCOUNTS reward and booking is made at least 24 hours before departure.
   * Algorithm:
   *   1. If customer is null or customer.membershipPackage is null → return this.price.
   *   2. If customer.membershipPackage.hasAward(Award.DISCOUNTS) is false → return this.price.
   *   3. Parse this.departureTime and bookingTime as datetime strings in format yyyy-MM-dd HH:mm.
   *      If parsing fails → return this.price.
   *   4. Compute the difference in hours: (departureTime - bookingTime) in hours.
   *   5. If difference >= 24.0 → return Math.round((this.price * 0.8) * 10.0) / 10.0.
   *   6. Otherwise → return this.price.
   * Related Features: price, departureTime, customer, customer.membershipPackage
   * Related Classes: Customer, MembershipPackage, Award
   * Input: customer : Customer - the customer making the booking; bookingTime : String - the booking datetime in yyyy-MM-dd HH:mm format.
   * Output: double - the discounted price (one decimal place) or the original price.
   * Pre-condition: None
   * Post-condition: No state changes. Returns the calculated price.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    // Step 1: If customer is null or customer.membershipPackage is null → return this.price.
    if (customer == null || customer.getMembershipPackage() == null) {
      return this.price;
    }
    
    // Step 2: If customer.membershipPackage.hasAward(Award.DISCOUNTS) is false → return this.price.
    if (!customer.getMembershipPackage().hasAward(Award.DISCOUNTS)) {
      return this.price;
    }
    
    // Step 3: Parse this.departureTime and bookingTime as datetime strings in format yyyy-MM-dd HH:mm.
    DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
    try {
      LocalDateTime departureDateTime = LocalDateTime.parse(this.departureTime, formatter);
      LocalDateTime bookingDateTime = LocalDateTime.parse(bookingTime, formatter);
      
      // Step 4: Compute the difference in hours: (departureTime - bookingTime) in hours.
      long diffHours = ChronoUnit.HOURS.between(bookingDateTime, departureDateTime);
      
      // Step 5: If difference >= 24.0 → return Math.round((this.price * 0.8) * 10.0) / 10.0.
      if (diffHours >= 24.0) {
        return Math.round((this.price * 0.8) * 10.0) / 10.0;
      }
    } catch (DateTimeParseException e) {
      // If parsing fails → return this.price.
      return this.price;
    }
    
    // Step 6: Otherwise → return this.price.
    return this.price;
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Computes the reward points earned by a customer for this trip during a given month.
   * Algorithm:
   *   1. If customer is null or customer.membershipPackage is null → return 0.
   *   2. If customer.membershipPackage.hasAward(Award.POINTS) is false → return 0.
   *   3. For each booking b in this.bookings:
   *      - If b.customer equals customer and b.bookingDate is not null:
   *        - Parse b.bookingDate as a datetime and check if its year-month matches currentMonth (yyyy-MM format).
   *        - If match → accumulate b.numberOfSeats.
   *   4. Return accumulated seats * 5.
   * Related Features: bookings, customer, bookings.bookingDate, bookings.numberOfSeats, customer.membershipPackage
   * Related Classes: Customer, MembershipPackage, Award, Booking, EDate
   * Input: customer : Customer - the customer whose points are calculated; currentMonth : String - month in yyyy-MM format.
   * Output: int - total reward points (5 per booked seat).
   * Pre-condition: None
   * Post-condition: No state changes. Returns points or 0.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    // Step 1: If customer is null or customer.membershipPackage is null → return 0.
    if (customer == null || customer.getMembershipPackage() == null) {
      return 0;
    }
    
    // Step 2: If customer.membershipPackage.hasAward(Award.POINTS) is false → return 0.
    if (!customer.getMembershipPackage().hasAward(Award.POINTS)) {
      return 0;
    }
    
    // Step 3: For each booking b in this.bookings:
    int accumulatedSeats = 0;
    DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
    
    for (Booking b : this.bookings) {
      // If b.customer equals customer and b.bookingDate is not null:
      if (b.getCustomer() == customer && b.getBookingDate() != null) {
        try {
          // Parse b.bookingDate as a datetime - convert to String first
          String bookingDateStr = b.getBookingDate().toString();
          LocalDateTime bookingDateTime = LocalDateTime.parse(bookingDateStr, formatter);
          // Check if its year-month matches currentMonth (yyyy-MM format)
          String bookingYearMonth = bookingDateTime.format(DateTimeFormatter.ofPattern("yyyy-MM"));
          if (bookingYearMonth.equals(currentMonth)) {
            // If match → accumulate b.numberOfSeats
            accumulatedSeats += b.getNumberOfSeats();
          }
        } catch (DateTimeParseException e) {
          // Skip this booking if parsing fails
          continue;
        }
      }
    }
    
    // Step 4: Return accumulated seats * 5.
    return accumulatedSeats * 5;
  }

